cat > "$build_dir/editor.html" <<'"'EOF'
<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pottery Market · Price Card Editor</title>
<style>
  :root {
    --ink: #000;
    --oxide: #943c2d;
    --paper: #fff;
    color: var(--ink);
    background: var(--paper);
    font-family: Arial, sans-serif;
  }
