    min-height: 2.7rem;
    border: 1px solid var(--ink);
    border-radius: 0;
    background: var(--paper);
    color: var(--ink);
    font: inherit;
  }
  input { padding: .45rem .65rem; width: 9rem; }
  input[aria-invalid="true"] { border: 2px solid var(--oxide); }
  button { padding: .6rem 1rem; cursor: pointer; font-weight: 700; }
  button:first-child { background: var(--ink); color: var(--paper); }
  button:hover:not(:disabled) { background: var(--oxide); border-color: var(--oxide); color: var(--paper); }
  button:disabled { opacity: .45; cursor: default; }
  :focus-visible { outline: 2px solid var(--oxide); outline-offset: 3px; }
  .directions { margin: .45rem 0 1rem; }
  .error { color: var(--oxide); font-weight: 700; }
  .preview {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr));
    gap: 1.5rem;
    margin-top: 2rem;
  }
  .sheet { margin: 0; }
  .sheet svg { display: block; height: auto; width: 100%; border: 1px solid var(--ink); }
  figcaption { font-weight: 700; padding: .6rem 0 0; }
  @page { size: letter portrait; margin: 0; }
  @media print {
    html, body, .workspace, .preview { display: block; width: auto; margin: 0; padding: 0; }
    .controls, figcaption { display: none; }
    .preview { break-inside: auto; }
    .sheet { position: relative; width: 8.5in; height: 10.99in; break-inside: avoid; break-after: page; }
    .sheet:last-child { break-after: auto; }
    .sheet svg { position: absolute; top: 0; left: 0; width: 8.5in; height: 11in; border: 0; }
    body.price-only .sheet:not(.price-sheet) { display: none; }
    body.invalid-prices .sheet, body.invalid-prices .preview { display: none; }
    body.invalid-prices .controls { display: block; padding: .5in; }
    body.invalid-prices .controls > :not(.error) { display: none; }
  }
</style>
</head>
<body>
<main class="workspace">
  <section class="controls" aria-labelledby="editor-title">
    <h1 id="editor-title">Rack price card editor</h1>
    <p>Change the prices below and print a fresh card sheet. The cards fit the dashed boxes on the three rack signs.</p>
    <div class="fields">
      <label>Small dishes ($)<input type="text" inputmode="decimal" data-product="small-dishes" value="8" aria-describedby="print-settings price-error"></label>
      <label>Planters ($)<input type="text" inputmode="decimal" data-product="planters" value="12" aria-describedby="print-settings price-error"></label>
      <label>Vases ($)<input type="text" inputmode="decimal" data-product="vases" value="18" aria-describedby="print-settings price-error"></label>
    </div>
    <p class="directions" id="print-settings">Use US Letter, 100% scale, with headers and footers off.</p>
    <p class="error" id="price-error" role="status" hidden>Enter a dollar amount from 0 to 999.99 with up to two decimal places.</p>
    <div class="actions">
      <button id="print-prices" type="button">Print price cards</button>
      <button id="print-kit" type="button">Print full kit</button>
    </div>
    <noscript><p>The preview shows the original prices. Enable JavaScript to change them or print just the card sheet.</p></noscript>
  </section>
  <section class="preview" aria-label="Print preview">
<!-- SHEETS -->
  </section>
</main>
<script>
  const fields = [...document.querySelectorAll('"'[data-product]')];
  const printPrices = document.querySelector('#print-prices');
  const printKit = document.querySelector('#print-kit');
  const priceError = document.querySelector('#price-error');

  function updatePrices() {
    let hasError = false;
    for (const field of fields) {
      const match = field.value.trim().match(/"'^'"\\"'$?('"\\d{1,3})(?:\\.(\\d{1,2}))?"'$/);
      field.setAttribute('"'aria-invalid', String("'!match));
      if (!match) {
        hasError = true;
        continue;
      }
      const dollars = String(Number(match[1]));
      const cents = (match[2] || '"'').padEnd(2, '0');
      const amount = '"'$'"' + dollars + (cents === '00' ? '' : '.' + cents);
      const cardPrice = document.querySelector('[data-price=\"' + field.dataset.product + '\"]');
      cardPrice.textContent = amount;
      cardPrice.setAttribute('font-size', amount.length <= 3 ? 73 : amount.length <= 5 ? 61 : 48);
    }
    priceError.hidden = "'!hasError;
    printPrices.disabled = hasError;
    printKit.disabled = hasError;
    document.body.classList.toggle('"'invalid-prices', hasError);
  }

  printPrices.addEventListener('click', () => {
    document.body.classList.add('price-only');
    window.print();
  });
  printKit.addEventListener('click', () => {
    document.body.classList.remove('price-only');
    window.print();
  });
  window.addEventListener('afterprint', () => document.body.classList.remove('price-only'));
  window.addEventListener('pageshow', updatePrices);
  fields.forEach(field => field.addEventListener('input', updatePrices));
  updatePrices();
</script>
</body>
</html>
