/bin/zsh -c 'build_dir=$(cat /tmp/pottery-market-build-path)
cat > "$build_dir/test-editor.cjs" <<'"'EOF'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');

const html = fs.readFileSync('Pottery Market - Price Card Editor.html', 'utf8');
const script = html.match(/<script>([\\s\\S]+)<\\/script>/)[1];
const classes = new Set();
const prints = [];

function element(props = {}) {
  return {
    ...props,
    attrs: {},
    events: {},
    setAttribute(key, value) { this.attrs[key] = value; },
    addEventListener(name, fn) { this.events[name] = fn; },
  };
}

const matches = [...html.matchAll(/<input ["'^>]*data-product="([''^"]+)" value="([''^"]+)"/g)];
const inputs = matches.map(([, product, value]) => element({dataset: {product}, value}));
const cards = Object.fromEntries(matches.map(([, product]) => ['"'[data-price=\"' + product + '\"]', element()]));
const output = Object.assign(cards, {
  '#print-prices': element(),
  '#print-kit': element(),
  '#price-error': element(),
});
const window = element({
  print() {
    prints.push([...classes]);
    this.events.afterprint();
  },
});
const document = {
  querySelectorAll: () => inputs,
  querySelector: id => output[id],
  body: {classList: {
    add: key => classes.add(key),
    remove: key => classes.delete(key),
    toggle(key, state) { if (state) classes.add(key); else classes.delete(key); },
  }},
};
vm.runInNewContext(script, {window, document});

const values = () => matches.map(([, product]) => cards['[data-price=\"' + product + '\"]'].textContent);
assert.deepEqual(values(), ['"'$8'"', '"'$12'"', '"'$18'"']);
for (const [i, value] of ['9.5', '999.99', ' "'$16.00 '"'].entries()) {
  inputs[i].value = value;
  inputs[i].events.input();
}
assert.deepEqual(values(), ['"'$9.50'"', '"'$999.99'"', '"'$16'"']);
output['#print-prices'].events.click();
output['#print-kit'].events.click();
assert.deepEqual(prints, [['price-only'], []]);
assert.equal(classes.has('price-only'), false);
for (const value of ['', 'oops', '1.111', '-1', '1000']) {
  inputs[1].value = value;
  inputs[1].events.input();
  assert.equal(inputs[1].attrs['aria-invalid'], 'true');
  assert.equal(output['#print-prices'].disabled, true);
  assert.equal(output['#print-kit'].disabled, true);
  assert.equal(output['#price-error'].hidden, false);
  assert.equal(classes.has('invalid-prices'), true);
}
inputs[1].value = '999.99';
inputs[1].events.input();
assert.equal(output['#print-prices'].disabled, false);
assert.equal(output['#price-error'].hidden, true);
assert.equal(classes.has('invalid-prices'), false);

const sheets = [...html.matchAll(/<svg [\\s\\S]+?<\\/svg>/g)].map(m => m[0]);
assert.equal(sheets.length, 6);
const updated = sheets[5].replace(/<text["'^>]+data-price="([''^"]+)"[''^>]*>[''^<]+<'"\\/text>/g, (tag, id) => {
  const card = cards['[data-price=\"' + id + '\"]'];
  return tag.replace(/font-size=\"["'^"]+"/, '"'font-size=\"' + card.attrs['font-size'] + '\"')
    .replace(/>["'^<]+<'"\\/text>/, '>' + card.textContent + '</text>');
});
fs.writeFileSync(process.argv[2], updated);
console.log('Passed default prices, updates with cents, invalid input, both print actions, and six-sheet markup.');
EOF
